import React from 'react';
import { ExternalLink, Clock, Target } from 'lucide-react';

const RoadmapItem = ({ gap }) => {
  return (
    <div className="glass-card p-5 rounded-2xl border border-scifi-600/30 mb-4 transition-all duration-300 hover:border-scifi-600/60 shadow-purple-glow">
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center space-x-2">
          <Target className="w-5 h-5 text-scifi-200" />
          <h4 className="font-heading font-bold text-lg text-scifi-100">{gap.skill}</h4>
        </div>
        <span className="px-3 py-1 rounded-full text-xs font-mono font-semibold border bg-scifi-600/30 text-scifi-100 border-scifi-600/50 shadow-purple-glow">
          {gap.priority || 'High'} Priority
        </span>
      </div>

      <div className="flex items-center space-x-2 text-xs font-mono text-scifi-200 mb-4">
        <Clock className="w-3.5 h-3.5 text-scifi-600" />
        <span>Estimated Mastery Time: {gap.estimated_time || '1-2 weeks'}</span>
      </div>

      {gap.resources && gap.resources.length > 0 && (
        <div className="pt-3 border-t border-scifi-600/20 space-y-2">
          <p className="text-[11px] font-mono uppercase tracking-wider text-scifi-200 font-semibold">
            Curated Learning Resources:
          </p>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
            {gap.resources.map((resource, index) => (
              <a
                key={index}
                href={resource.url}
                target="_blank"
                rel="noopener noreferrer"
                className="p-2.5 rounded-xl bg-scifi-950/80 border border-scifi-600/20 flex items-center justify-between text-xs text-scifi-200 hover:text-scifi-100 hover:border-scifi-600/60 hover:bg-scifi-800/60 transition-all group"
              >
                <span className="truncate">{resource.name}</span>
                <ExternalLink className="w-3.5 h-3.5 text-scifi-600 group-hover:scale-110 transition-transform shrink-0 ml-2" />
              </a>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default RoadmapItem;
